using System.Text.RegularExpressions;

public record Stats(int Words, int Distinct, string Longest, List<(string Word, int Count)> Top3);

public static class WordStats
{
    public static Stats Of(string text)
    {
        var words = Regex.Matches(text, "[A-Za-z']+").Select(m => m.Value.ToLowerInvariant()).ToList();
        var top = words.GroupBy(w => w)
            .Select(g => (Word: g.Key, Count: g.Count()))
            .OrderByDescending(x => x.Count)
            .ThenBy(x => x.Word, StringComparer.Ordinal)
            .Take(3)
            .ToList();
        string longest = words.Count == 0 ? "" : words.MaxBy(w => w.Length)!;
        return new Stats(words.Count, words.Distinct().Count(), longest, top);
    }
}

unitTests:
Test("counts and top words", () =>
{
    var s = WordStats.Of("The cat sat. The cat sat on THE mat, the end.");
    CheckEq(s.Words, 11);
    CheckEq(s.Distinct, 6);
    CheckEq(string.Join(",", s.Top3.Select(t => $"{t.Word}:{t.Count}")), "the:4,cat:2,sat:2");
});

Test("longest takes the first on a tie", () =>
{
    CheckEq(WordStats.Of("tea coffee cocoa latte").Longest, "coffee");
    CheckEq(WordStats.Of("abc abd").Longest, "abc");
});

Test("apostrophes stay inside words", () =>
{
    CheckEq(WordStats.Of("don't stop, don't").Top3[0], ("don't", 2));
});

Test("no words", () =>
{
    var s = WordStats.Of("123 ... !!!");
    CheckEq((s.Words, s.Distinct, s.Longest, s.Top3.Count), (0, 0, "", 0));
});

